//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");

//#include("../js/pre_newlisting.js");

scwin.vScrenID = "ULDSTF08026.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vIsurCd = ""; //발행회사코드
scwin.vIsurNm = ""; //발행회사명
scwin.vIsuCd = ""; //종목코드
scwin.vIsuNm = ""; //종목명
scwin.vIsuAbbrv = ""; //종목약명

scwin.v_SaveKind = ""; //신규,수정 구분

scwin.TR_JOB;
scwin.vListBzTpCd = LIST_BZ_TP_CD_709; //종목명변경
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;
scwin.vIsuNmChg = ""; // 종목명변경 Y/N
scwin.vIsuQtyChg = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 수량변경 Y/N

/********************************************** 
 * 함수명 : fn_select_read_init()
 * 설명    : 종목명변경 상장내역 조회
 ***********************************************/
scwin.fn_select_read_init = function() {
    var url = "";
    var srvMethod = "";
    if (scwin.v_SaveKind == 'N') {
        srvMethod = "selectIsuNmChgForNew";
    } else if (scwin.v_SaveKind == 'U') {
        srvMethod = "selectIsuNmChgDetail";
    }
    url = "/etn/EtnChgList.do?method=" + srvMethod;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    url += "&SRCH_COM_CD=";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&ACPT_NO=" + vAcptNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();
    if (scwin.v_SaveKind == 'N') {
        $c.stf.setObjectValue(txb_AFCHG_ISU_NM, dts_Isu.getCellData(1, "BFCHG_ISU_NM"));
        $c.stf.setObjectValue(txb_AFCHG_ISU_ABBRV1, dts_Isu.getCellData(1, "BFCHG_ISU_ABBRV"));
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_NM, dts_Isu.getCellData(1, "BFCHG_ISU_ENG_NM"));
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_ABBRV1, dts_Isu.getCellData(1, "BFCHG_ISU_ENG_ABBRV"));
        //vAcptNo = parentWin.clickAcptNo;	//접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)
        //vAcptNo = dts_Isu.NameValue(1, "ACPT_NO");

    } else {
        //vAcptNo = parentWin.clickAcptNo;	//접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

        //vAcptNo = dts_Isu.NameValue(1, "ACPT_NO");

    }
    scwin.vIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.vIsurNm = dts_Isu.getCellData(1, "ISUR_NM");
    scwin.vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsuAbbrv = dts_Isu.getCellData(1, "ISU_ABBRV");
};


/********************************************** 
 * 함수명 : fn_CheckForm()
 * 설명    : Form Validation Check
 ***********************************************/
scwin.fn_CheckForm = function() {
    if (scwin.vIsuCd == "") {
        $c.win.alert("[종목]이 조회되어 있지 않습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    //Check Max Length
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_NM) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_NM))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_NM, 80, "한글종목명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ABBRV1, 40, "한글종목약명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_ABBRV1, 40, "영문종목약명")) return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명 : fn_SetFormField()
 * 설명    : 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 
 *             현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함
 ***********************************************/
scwin.fn_SetFormField = function() {
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_NM))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_NM, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ABBRV1, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_NM, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_ABBRV1, "");
    }
};



/********************************************** 
 * 함수명 : fn_save()
 * 설명    : 종목명 변경상장 내역 > 신규저장
 ***********************************************/
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm() && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo == undefined || scwin.vBzProcsNo == "") {
            scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};




/********************************************** 
 * 함수명 : fn_update()
 * 설명    : 종목명 변경상장 내역 > 수정
 ***********************************************/
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm() && scwin.fn_dupCheck()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;

        /*if (vSecuGrpId == SECUGRP_ID_EN) {
        		fn_checkSave();
        }*/

        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};



/********************************************** 
 * 함수명 : fn_delete()
 * 설명    : 종목명 변경상장 내역 > 삭제
 ***********************************************/
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
    scwin.fn_trs(TRS_IDX_DELETE);
};


/********************************************** 
 * 함수명 : fn_trs(trxIdx)
 * 설명    : 트랜잭션 처리 구분(저장,수정,삭제)
 ***********************************************/
scwin.fn_trs = function(trsIdx) {
    var srvMethod = "";
    var trsKind;
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        srvMethod = "insertIsuNmChgDtl";
        trsKind = TR_JOB_INSERT;
        scwin.fn_SetFormField();
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
        srvMethod = "updateIsuNmChgDtl";
        trsKind = TR_JOB_UPDATE;
        scwin.fn_SetFormField();
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
        srvMethod = "deleteIsuNmChgDtl";
        trsKind = TR_JOB_DELETE;
    }
    trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnChgList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=" + srvMethod);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsKind + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + scwin.vIsurCd + ",ISU_CD=" + scwin.vIsuCd + ",ACPT_NO=" + vAcptNo;
    trs_Save.Post();
};


/********************************************** 
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.fn_dscl = async function() {
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    var cCtnt = "";
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "68354";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = '1';
        arr[4] = scwin.fn_getItmChgDisclsCtnt(); //ctnt
        arr[5] = $c.stf.getObjectValue(txb_BFCHG_ISU_ABBRV); //add  title

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);

        //param_dts_mst.NameString(param_dts_mst.RowPosition, "TGT_NM") = Isur_nm ;

        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 25;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "상장지수증권 변경상장 안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;

    //안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_chglist_sync();
};


/********************************************** 
 * 함수명 : fn_getItmChgDisclsCtnt()
 * 설명    : 안내문작성 서식 (종목명변경)
 ***********************************************/
scwin.fn_getItmChgDisclsCtnt = function() {
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_NM).length > 0 || $c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1).length > 0 || $c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM).length > 0 || $c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1).length > 0) {
        scwin.vIsuNmChg = "Y";
    } else {
        scwin.vIsuNmChg = "N";
    }
    if (($c.stf.getObjectValue(txb_CHG_ETN_ISU_QTY).length > 0 || $c.stf.getObjectValue(txb_ETN_CONSLDT_RTO).length > 0 || $c.stf.getObjectValue(txb_ETN_SPLIT_RTO).length > 0) &&
        ($c.stf.getObjectValue(txb_CHG_ETN_ISU_QTY) > 0 || $c.stf.getObjectValue(txb_ETN_CONSLDT_RTO) > 0 || $c.stf.getObjectValue(txb_ETN_SPLIT_RTO) > 0)) {
        scwin.vIsuQtyChg = "Y";
    } else {
        scwin.vIsuQtyChg = "N";
    }
    var vCtnt = "";
    var vConsldtRto = $c.stf.getObjectValue(txb_ETN_CONSLDT_RTO);
    var vSplitRto = $c.stf.getObjectValue(txb_ETN_SPLIT_RTO);
    if (vConsldtRto == "0") vConsldtRto = "-";
    if (vSplitRto == "0") vSplitRto = "-";
    vCtnt += "[공시제목] 상장지수증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + scwin.vIsurNm + " 발행 상장지수증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "다음과 같이 " + $c.stf.getObjectValue(txb_BFCHG_ISU_ABBRV) + "의 변경상장 내역을 알려드립니다.";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 변경내역";
    if (scwin.vIsuNmChg == "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 한글종목명";
        vCtnt += "\r\n";
        vCtnt += "    변경전: " + $c.stf.getObjectValue(txb_BFCHG_ISU_NM) + " (약명 : " + $c.stf.getObjectValue(txb_BFCHG_ISU_ABBRV) + ")";
        vCtnt += "\r\n";
        vCtnt += "    변경후: " + $c.stf.getObjectValue(txb_AFCHG_ISU_NM) + " (약명 : " + $c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1) + ")";
        vCtnt += "\r\n\r\n";
        vCtnt += " - 영문종목명";
        vCtnt += "\r\n";
        vCtnt += "    변경전: " + $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_NM) + " (약명 : " + $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_ABBRV) + ")";
        vCtnt += "\r\n";
        vCtnt += "    변경후: " + $c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM) + " (약명 : " + $c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1) + ")";
    }
    if (scwin.vIsuQtyChg == "Y") {
        vCtnt += "\r\n\r\n";
        vCtnt += " - 병합ㆍ분할";
        vCtnt += "\r\n";
        vCtnt += "    병합비율: " + vConsldtRto;
        vCtnt += "\r\n";
        vCtnt += "    분할비율: " + vSplitRto;
        vCtnt += "\r\n";
        vCtnt += "    변경전 상장수량: " + $c.stf.addComma($c.stf.getObjectValue(txb_ETN_ISU_QTY));
        vCtnt += "\r\n";
        vCtnt += "    변경후 상장수량: " + $c.stf.addComma($c.stf.getObjectValue(txb_CHG_ETN_ISU_QTY));
    }
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 변경 사유 : " + txb_CHG_RSN.getText();
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 변경상장일 : " + scwin.dateForm($c.stf.getObjectValue(edt_CHG_LIST_DD));
    vCtnt += "\r\n\r\n";
    return vCtnt;
};


/********************************************** 
 * 함수명 : dateForm()
 * 설명    : 년월일 포맷 맞춤 (안내문 작성에서 사용)
 ***********************************************/
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};


/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_chglist_sync;
    fr_fn_list_sync();
};


/********************************************** 
 * 함수명 : fn_parentRefresh2()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
/*function fn_parentRefresh2() {
	//Parent 신청내역 화면 Refresh
	var parentWin = frame.Provider("../");		
	parentWin.txb_SearchIsuCd2.value = vIsuCd;
	parentWin.txb_SearchIsuNm2.value = vIsuAbbrv;
	setObjectValue(parentWin.cmb_ISUR_CD2, vIsurCd);
	parentWin.fn_list_chglist_appl(vIsurCd, vIsuCd);
	parentWin.fn_list_chglist_sync();
}
*/

/********************************************** 
 * 함수명 : fn_dupCheck()
 * 설명    : 종목 중복날짜 체크
 ***********************************************/
scwin.fn_dupCheck = function() {
    var chgDd = $c.stf.getObjectValue(edt_CHG_LIST_DD);
    var isNotDup = true;
    url = "/etn/EtnChgList.do?method=selectIsuNmChgDupList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISU_CD=" + scwin.vIsuCd + "&CHG_DD=" + chgDd + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_DupChk.DataID = encodeURI(url);
    dts_DupChk.reset();
    if (dts_DupChk.getTotalRow() > 0) {
        isNotDup = false;
        $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {

};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    //저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lce.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vSecuGrpId = parentWin.fr_SecuGrpId;

    //
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    //buttonSet.setDeleteInfo( btn_RecvIsuDel, fn_delete ); 	// 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    /*	
    if (vSecuGrpId == SECUGRP_ID_EN) {
    	txb_memo.disabled = false;
    	txb_memo.value = "(미입력시 '변경전' 값이 저장됩니다.)";
    } else {
    	txb_memo.disabled = true;
    }
    */
    //Parent Data
    scwin.v_SaveKind = parentWin.vIsuNmChgKind; //Transaction 구분: 신규(N), 수정(U)
    //v_UpdParam = parentWin.v_UpdItmIsurParam;	//변경상장내역 Param

    if (scwin.v_SaveKind == "N") {
        scwin.vBzProcsNo = ""; //업무처리번호
        scwin.vIsuCd = $c.stf.getObjectValue(parentWin.txb_SearchIsuCd2); //종목코드
        vAcptNo = parentWin.clickAcptNo; //접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

        //수정,삭제 버튼 비활성화
        btn_Update.src = "../img/btn_modify_d.gif";
        btn_Update.setDisabled(true);
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_RecvIsuDel.setDisabled(true);
        btn_Dscl.src = "../img/btn_make_info_d.gif";
        btn_Dscl.setDisabled(true);
    } else {
        scwin.vBzProcsNo = parentWin.clickBzProcsNo; //업무처리번호
        scwin.vIsuCd = parentWin.clickIsuCd; //종목코드
        vAcptNo = parentWin.clickAcptNo; //접수번호 (참고: 상세조회에서 접수번호를 들고 오니 향후참고)

        btn_Save.src = "../img/btn_save_d.gif";
        btn_Save.setDisabled(true);
        if (parentWin.clickDisclsYn == "Y") {
            btn_Update.src = "../img/btn_modify_d.gif";
            btn_Update.setDisabled(true);
            btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
            btn_RecvIsuDel.setDisabled(true);
            btn_Dscl.src = "../img/btn_make_info_d.gif";
            btn_Dscl.setDisabled(true);
        }
    }

    //데이터 조회
    scwin.fn_select_read_init();
};
